document:
query CustomerAddresses($id: ID!) {
  user(id: $id) {
    ...CustomerAddresses
  }
}

fragment CustomerAddresses on User {
  ...Customer
  addresses {
    ...Address
  }
  defaultBillingAddress {
    id
  }
  defaultShippingAddress {
    id
  }
}

fragment Customer on User {
  id
  email
  firstName
  lastName
}

fragment Address on Address {
  city
  cityArea
  companyName
  country {
    __typename
    code
    country
  }
  countryArea
  firstName
  id
  lastName
  phone
  postalCode
  streetAddress1
  streetAddress2
}
